def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the full divider line.
    sep_row = next((r for r in range(h) if all(v == 2 for v in grid[r])), None)
    sep_col = next((c for c in range(w) if all(grid[r][c] == 2 for r in range(h))), None)

    bg_counts = {}
    for row in grid:
        for v in row:
            if v != 2:
                bg_counts[v] = bg_counts.get(v, 0) + 1
    bg = max(bg_counts, key=bg_counts.get)

    obj = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
           if grid[r][c] != 2 and grid[r][c] != bg]
    if not obj:
        return [row[:] for row in grid]

    out = [[bg] * w for _ in range(h)]

    if sep_row is not None:
        out[sep_row] = grid[sep_row][:]
        rows = [r for r, c, v in obj]
        if max(rows) < sep_row:  # object above divider
            shift = sep_row - 1 - max(rows)
            moved = [(r + shift, c, v) for r, c, v in obj]
            stripe = min(r for r, c, v in moved) - 1
        else:  # object below divider
            shift = sep_row + 1 - min(rows)
            moved = [(r + shift, c, v) for r, c, v in obj]
            stripe = max(r for r, c, v in moved) + 1
        for r, c, v in moved:
            out[r][c] = v
        if 0 <= stripe < h:
            out[stripe] = [8] * w

    elif sep_col is not None:
        for r in range(h):
            out[r][sep_col] = 2
        cols = [c for r, c, v in obj]
        if max(cols) < sep_col:
            shift = sep_col - 1 - max(cols)
            moved = [(r, c + shift, v) for r, c, v in obj]
            stripe = min(c for r, c, v in moved) - 1
        else:
            shift = sep_col + 1 - min(cols)
            moved = [(r, c + shift, v) for r, c, v in obj]
            stripe = max(c for r, c, v in moved) + 1
        for r, c, v in moved:
            out[r][c] = v
        if 0 <= stripe < w:
            for r in range(h):
                out[r][stripe] = 8

    return out
